<script setup>
import {ref,computed} from 'vue'; import AdminLayout from '../layouts/AdminLayout.vue'; import PageHeader from '../components/PageHeader.vue'; import {store,persist} from '../mockStore'
const search=ref(''),selected=ref(store.clients[0]||null),show=ref(false),form=ref({name:'',phone:'',email:''}),msg=ref('')
const clients=computed(()=>store.clients.filter(c=>`${c.name} ${c.phone} ${c.email}`.toLowerCase().includes(search.value.toLowerCase())))
function add(){if(!form.value.name)return;const id=Math.max(0,...store.clients.map(c=>c.id))+1;const c={id,...form.value,devices:[]};store.clients.push(c);selected.value=c;form.value={name:'',phone:'',email:''};show.value=false;persist();msg.value='Cliente agregado al prototipo local.'}
</script>
<template><AdminLayout><PageHeader>Clientes y equipos<template #subtitle>Directorio y relación de equipos del cliente.</template><template #actions><button class="btn btn-primary" @click="show=!show">+ Nuevo cliente</button></template></PageHeader><div v-if="msg" class="alert alert-success py-2">{{msg}}</div><div v-if="show" class="mc-card p-3 mb-3"><div class="row g-2"><div class="col-md-4"><input v-model="form.name" class="form-control" placeholder="Nombre"></div><div class="col-md-3"><input v-model="form.phone" class="form-control" placeholder="Teléfono"></div><div class="col-md-3"><input v-model="form.email" class="form-control" placeholder="Correo"></div><div class="col-md-2"><button class="btn btn-primary w-100" @click="add">Guardar demo</button></div></div></div><div class="row g-3"><div class="col-lg-5"><div class="mc-card p-3"><input v-model="search" class="form-control mb-3" placeholder="Buscar cliente..."><div class="list-group list-group-flush"><button v-for="c in clients" class="list-group-item list-group-item-action" @click="selected=c"><strong>{{c.name}}</strong><div class="small text-muted">{{c.phone}} · {{c.email}}</div></button></div></div></div><div class="col-lg-7"><div v-if="selected" class="mc-card p-4"><h5>{{selected.name}}</h5><div class="text-muted">{{selected.phone}} · {{selected.email}}</div><hr><h6>Equipos asociados</h6><div v-if="!selected.devices.length" class="empty-state">Sin equipos registrados.</div><div v-for="d in selected.devices" class="mc-card p-3 mb-2"><strong>{{d.brand}} {{d.model}}</strong><div class="small text-muted">{{d.type}} · {{d.identifier}}</div></div></div></div></div></AdminLayout></template>
